import{_ as o,a0 as p,w as r,s as l,ao as d,I as n,x as a,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Linux 上搭建 Minecraft 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 上搭建 Minecraft 服务器 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 上搭建 Minecraft 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 上搭建 Minecraft 服务器 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20161225 Minecraft Server on Linux","title":"Linux 上搭建 Minecraft 服务器","tag":"201701","desc":""},"relativePath":"201701/20161225 Minecraft Server on Linux.md","filePath":"[post].md"}'),c={name:"201701/20161225 Minecraft Server on Linux.md"};function h(u,e,g,f,m,b){const s=p("Link");return r(),l("div",null,[e[13]||(e[13]=d(`<h1 id="linux-上搭建-minecraft-服务器" tabindex="-1">Linux 上搭建 Minecraft 服务器 <a class="header-anchor" href="#linux-上搭建-minecraft-服务器" aria-label="Permalink to “Linux 上搭建 Minecraft 服务器”">​</a></h1><p><img src="https://www.linuxforum.com/attachments/title-jpg.89/" alt="Title.jpg"></p><p>“我的世界（Minecraft）”是一个人们可以在各种游戏主机和计算机上玩的主流游戏。 截止至 2016 年 6 月，在各种平台上已经售出了超过十亿六千万份。因其受欢迎，你可能想在家里举办一个“我的世界”派对，那么你就需要安装一个 “我的世界” 服务器，让所有的玩家连接到同一个世界中一起玩。</p><h3 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to “系统要求”">​</a></h3><p>要开始的话，你需要一个有相当数量内存的 Linux 操作系统。你要在服务器上容纳的玩家越多，你就需要越多的内存。硬盘空间倒不是需求很大，只要足够去安装 Java 以及“我的世界”服务器 Java 文件就行。Minecraft 服务器需要有一个稳定的网络连接，不管是有线还是无线网络。</p><p>让我们看看 “我的世界”服务器最低要求：</p><ul><li><strong>CPU：</strong>双核或更好。</li><li><strong>内存：</strong> 2 GB （20-40 用户量)，3 GB（30-60 用户量），8 GB（60+ 用户量）。</li><li><strong>系统：</strong> 不需要图形化用户接口，可以留出更多的空闲资源。</li></ul><p><strong>备注：</strong> 这是“我的世界” 服务端程序的需求，而不是一个完整的操作系统的需求。如果可以给我的世界服务器分配更多的资源，它将运行得更好。</p><p>###安装 Java</p><p>如果你用 Linux 操作系统运行它的话，你需要安装最新版本的 Java 环境。</p><p>为了验证你的 Java 版本，位于终端输入以下命令：<code>java -version</code>。结果应该是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>java version &quot;1.8.0_101&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Java(TM) SE Runtime Environment (build 1.8.0_101-b13)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Java HotSpot(TM) Client VM (build 25.101-b13, mixed mode)</span></span></code></pre></div><p>如果你当前的 Java 版本不是 1.8 或者更高，则通过在 Ubuntu 系统的终端下执行以下操作来安装 Java 版本 8：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:webupd8team/java</span></span>
<span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install oracle-java8-installer</span></span></code></pre></div><p><strong>注意：</strong>如果 <code>add-apt-repository</code> 命令无法找到，运行 <code>sudo apt-get install software-properties-common</code> 来安装。 您还可以将第三个命令中更改为 <code>oracle-java9-installer</code> 来安装最新的 java 版本。</p><p>对于 Redhat 系统（如 CentOS），请使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install java-1.8.0-openjdk</span></span></code></pre></div><p>安装后，核实键入版本命令 <code>java-version</code> ，并且核实输出。这样你就有了一个适当的 Java 版本，你可以继续进行接下来的安装。</p><h3 id="我的世界-服务器版本下载" tabindex="-1">“我的世界”服务器版本下载 <a class="header-anchor" href="#我的世界-服务器版本下载" aria-label="Permalink to ““我的世界”服务器版本下载”">​</a></h3><p>接下来做的事就是去检查用户将运行的“我的世界”的版本。图 1 显示了一个正在运行的 ”我的世界“ ，注意左下角的版本号。</p><p><img src="https://www.linuxforum.com/attachments/figure-01-jpg.85/" alt="Figure 01.jpg"></p><p><em>图 1</em></p><p>请记住“我的世界”客户端版本号。每个客户端应该是相同的版本才行。</p><p>您接下来要做的是下载客户端所需要的“我的世界”的服务器版本。为了下载该版本你需要知道它的位置。得到所需的文件的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo wget https://s3.amazonaws.com/Minecraft.Download/versions/[version]/minecraft_server.[version].jar</span></span></code></pre></div><p>在 图1 看到，版本号是 1.10.2。那么这个命令就该变成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo wget https://s3.amazonaws.com/Minecraft.Download/versions/1.10.2/minecraft_server.1.10.2.jar</span></span></code></pre></div><p>当你下载好文件，会保存到你当前目录下。使用命令 <code>pwd</code> 确定当前位置。</p><p>一旦你有了该文件，知道它所保存的文件夹就可以继续了。</p><h3 id="服务器信息" tabindex="-1">服务器信息 <a class="header-anchor" href="#服务器信息" aria-label="Permalink to “服务器信息”">​</a></h3><p>在启动“我的世界”服务器之前，您必须知道当前系统上能被你使用的可用内存大小。 当启动“我的世界”服务器时，你将需要指定起始内存量和当更多玩家加入时最大分配的内存量。 再次提示，重要的是要有足够的内存。 如果可以，使用最小化安装操作系统来留出更多的内存，例如最小化安装的 Ubuntu。</p><p>一旦你有了所需的“我的世界”服务器文件，就可以确定分配给“我的世界”的内存数量。 要确定可用内存，打开一个终端并键入以下命令 ，示例输出如图 2 所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>free -h</span></span></code></pre></div><p><img src="https://camo.githubusercontent.com/686cb2c9421f276e1cab0b08b713f636ed3ca614/68747470733a2f2f7777772e6c696e7578666f72756d2e636f6d2f6174746163686d656e74732f6669677572652d30322d6a70672e38362f" alt="Figure 02.jpg"></p><p><em>图 2</em></p><p>如图 2 所示，在这个低端系统上你可以看到那只有 684 MB 空闲内存。这不是一个可以用于搭建一个 “我的世界” 服务器的系统。在另一个服务器上我有 2.8 GB 内存可供给“我的世界” 使用。</p><p>在我们启动服务器之前，我们需要找到服务器的 IP 地址。 为此，请运行命令 <code>ifconfig</code>。 如图 3 所示，应该列出了网络连接，显示 <code>Internet Address</code> 或 <code>inet addr</code>，这里是 <code>192.168.0.2</code>。 在我的服务器系统上，它列出的地址是 <code>192.168.0.14</code>，这个地址是客户端系统将要使用的地址。</p><p><img src="https://camo.githubusercontent.com/62dc2bfe97f8df7895d606c594d74f27b4881ee4/68747470733a2f2f7777772e6c696e7578666f72756d2e636f6d2f6174746163686d656e74732f6669677572652d30332d6a70672e38372f" alt="Figure 03.jpg"></p><p><em>图 3</em></p><h3 id="启动-我的世界-服务器" tabindex="-1">启动“我的世界”服务器 <a class="header-anchor" href="#启动-我的世界-服务器" aria-label="Permalink to “启动“我的世界”服务器”">​</a></h3><p>下一步才是真正的启动“我的世界”服务器。在我们实际开始前，会涉及到几个选项。当启动“我的世界”服务器时，你需要指定用多少内存来初始化“我是世界”。 您还将指定使用的最大内存量。</p><p>如果我的系统有 3.7GB 闲置内存，我知道会有不到 40 位玩家，于是我只需要划出 2GB。当然，我可以增加些以允许用户增长。如果需要的话，我还可以留一点内存给系统运行。我将最小值设置为 2 GB，最大值设置为 3 GB。 由于最大值设置为 3 GB，如果需要的话，还可以至少留给系统 700 MB 内存，但这只有在“我的世界”服务器使用超过最初分配的2 GB 时才会发生。</p><p>启动服务器的命令行是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo java -Xms# -Xmx# -jar [path]/minecraft_server.[version].jar nogui</span></span></code></pre></div><p>现在解释一下命令结构：</p><ul><li>-Xms# - 初始启动分配的内存（<code>-Xms2048m</code>）</li><li>-Xmx# - 最大分配的内存（<code>-Xmx3096m</code>）</li><li>[path] – “我的世界” 服务器文件路径（ <code>/home/tux/MCS/</code>）</li><li>[version] – 下载的“我的世界” 服务器的版本（<code>1.10.2</code>）</li><li>nogui – 用于以基于文本的界面来显示，可以减少内存使用。如果你使用图形化界面，那么移除 <code>nogui</code> 选项。</li></ul><p>一个使用 2GB 内存以及最大 3GB、位置为 <code>/home/tux/MCS</code>、 版本号为 <code>1.10.2</code> 的系统的完整命令实例是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo java -Xms2048m -Xmx3096m -jar /home/tux/MCS/minecraft_server.1.10.2.jar nogui</span></span></code></pre></div><p><strong>注意：</strong> 这里内存容量的大小是兆字节单位。容量要乘以 1024。举个例子，2GB 的内存使 2 与 1024 相乘，容量为 2048。但别忘小写字母 <code>m</code> 是特指兆字节。你可以简单地使用特指的 <code>2g</code> 和 <code>3g</code> 来表示 2GB 和 3GB。</p><p>在你首次运行服务器时会发成一些错误。开始之前，它表明需要同意 “最终用户许可协议 EULA”。</p><p>要同意 “最终用户许可协议 EULA”，你需要编辑与“我的世界”服务器 JAR 文件同一文件夹下的的 <code>eula.txt</code> 文件。</p><p>使用一个类似 <code>nano</code> 的文件编辑器打开文件 <code>eula.txt</code> 文件。确定你进行这步时使用的是 root 权限。将行 <code>eula = false</code> 更改为 <code>eula = true</code>，并保存文件。</p><p>现在，再次输入上述命令以启动服务器。 应该滚过满屏幕信息，然后一个状态行将显示它的创建过程。 当其这个初始世界创建好之后，状态行将显示 100％。 有关系统时间更改的任何错误消息是正常的，因此忽略它们。</p><p>此时，你可以打开客户端程序并且看到如上图 1 的界面。点击“Multiplayer”按钮。在下一屏幕，如图 4，选择 “Direct Connect”，这将提示您输入服务器地址，因此键入“我的世界”服务器的 IP 地址。你现在应该已经连接到游戏了。</p><p><img src="https://camo.githubusercontent.com/6893151530092ac59b7b04d17ca5bc07d9bfc9b4/68747470733a2f2f7777772e6c696e7578666f72756d2e636f6d2f6174746163686d656e74732f6669677572652d30342d6a70672e38382f" alt="Figure 04.jpg"></p><p><em>图 4</em></p><h3 id="连接的某些麻烦" tabindex="-1">连接的某些麻烦 <a class="header-anchor" href="#连接的某些麻烦" aria-label="Permalink to “连接的某些麻烦”">​</a></h3><p>如果一些客户端无法连接到服务器，那么你需要按下 <code>CTRL+Z</code> 退出 Java 程序。打开文件 <code>server.propertices</code>， 使用一个 nano 之类的编辑器进行编辑。记住要 root 权限。编辑 <code>online-mode</code> 行，它应该设置为 <code>true</code> ，修改为 <code>false</code> 并保存。重启服务器并打开“我的世界”服务器。使用客户端重新连接到服务器，现在应该一切都好了。</p><p>建设快乐！</p><hr>`,60)),n("p",null,[e[1]||(e[1]=a("via: ",-1)),i(s,{href:"https://www.linuxforum.com/threads/minecraft-server-on-linux.3202/"},{default:t(()=>[...e[0]||(e[0]=[a("https://www.linuxforum.com/threads/minecraft-server-on-linux.3202/",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=a("作者：",-1)),i(s,{href:"https://www.linuxforum.com/members/jarret.268/"},{default:t(()=>[...e[2]||(e[2]=[a("Jarret",-1)])]),_:1}),e[6]||(e[6]=a(" 译者：",-1)),i(s,{href:"http://www.itxdm.me"},{default:t(()=>[...e[3]||(e[3]=[a("erlinux",-1)])]),_:1}),e[7]||(e[7]=a(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=a("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[a("Linux中国",-1)])]),_:1}),e[12]||(e[12]=a(" 荣誉推出",-1))])])}const C=o(c,[["render",h]]);export{x as __pageData,C as default};
